/// <summary>
/// Bug 340986: E2E - Demand - CB201 - Post Provision Batch Job unsuccessful + Full Rebate Value = Write Off
/// </summary>
[
SysOperationJournaledParametersAttribute(true)
]
public class METTAMRebateCreateTransController_WriteOff extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// New method
/// </summary>
/// <param name = "_className">TAMRebateCreateTransService</param>
/// <param name = "_methodName">TAMRebateCreateTransService\process</param>
/// <param name = "_executionMode">Synchronous</param>
protected void new(
    IdentifierName _className = classStr(TAMRebateCreateTransService),
    IdentifierName _methodName = methodStr(TAMRebateCreateTransService, process),
    SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    super(_className, _methodName, _executionMode);
}

/// <summary>
/// When this is manually created from the batch job journal, we need to default the RebateTransactionType (hidden) to the right value
/// </summary>
/// <returns></returns>
protected container packDataContractInfoObjects()
{
    container ret;

    ret = super();

    container packedContractContainer = conPeek(ret, 2);

    ret = METTAMRebateContractHelper::updateRebateTransactionTypeInPackedContract(ret, TAMRebateTransactionType::WriteOff);

    return ret;
}

/// <summary>
/// defaultCaption
/// </summary>
/// <returns>defaultCaption</returns>
protected ClassDescription defaultCaption()
{
    return "Create rebate management transactions - Write off";
}
